from google.cloud import translate_v3

class TranslationClient:
    def __init__(self, project_id: str, location: str = "global"):
        self.client = translate_v3.TranslationServiceClient()
        self.parent = f"projects/{project_id}/locations/{location}"

    def translate_text(self, texts: list[str], source_language: str, target_language: str, mime_type: str = "text/plain") -> list[str]:
        response = self.client.translate_text(
            request={
                "parent": self.parent,
                "contents": texts,
                "mime_type": mime_type,
                "source_language_code": source_language,
                "target_language_code": target_language,
            }
        )
        return [translation.translated_text for translation in response.translations]

from typing import Dict, Any
from translation_client import TranslationClient
from translation_models import DictionaryTranslationRequest, DictionaryTranslationResponse

def translate_dictionary_values(payload: DictionaryTranslationRequest, config: dict) -> DictionaryTranslationResponse:
    client = TranslationClient(project_id=config["project_id"], location=config.get("location", "global"))

    values_to_translate = list(payload.data.values())
    translated_values = client.translate_text(
        texts=values_to_translate,
        source_language=payload.source_language,
        target_language=payload.target_language,
    )

    translated_data = {}
    keys = list(payload.data.keys())
    for i, key in enumerate(keys):
        translated_data[key] = translated_values[i]

    return DictionaryTranslationResponse(
        translated_data=translated_data,
        source_language=payload.source_language,
        target_language=payload.target_language,
    )

from google.cloud import language_v1
from typing import Dict, Any

def quality_summary(payload: Dict[str, str], config: Dict[str, Any]) -> Dict[str, Any]:
    client = language_v1.LanguageServiceClient()
    document = language_v1.Document(
        content=payload["translated_text"],
        type_=language_v1.Document.Type.PLAIN_TEXT,
        language=payload["target_language"],
    )
    sentiment = client.analyze_sentiment(request={
        "document": document,
        "encoding_type": language_v1.EncodingType.UTF8
    }).document_sentiment

    return {
        "translated_text": payload["translated_text"],
        "sentiment_score": sentiment.score,
        "sentiment_magnitude": sentiment.magnitude,
        "summary": f"Sentiment score: {sentiment.score}, Magnitude: {sentiment.magnitude}"
    }

from google.cloud import language_v1
from typing import Dict, Any, List

def unsafe_copy_check(payload: Dict[str, str], config: Dict[str, Any]) -> Dict[str, Any]:
    client = language_v1.LanguageServiceClient()
    document = language_v1.Document(
        content=payload["translated_text"],
        type_=language_v1.Document.Type.PLAIN_TEXT,
        language=payload["target_language"],
    )

    # This is a basic example; a real-world unsafe content check would involve more sophisticated logic
    # and potentially other dedicated content moderation APIs.
    response = client.analyze_entities(request={
        "document": document,
        "encoding_type": language_v1.EncodingType.UTF8
    })

    unsafe_indicators = [
        "violence", "hate speech", "sexual content", "profanity",
        "drugs", "weapons", "terrorism",
    ]

    found_unsafe_terms: List[str] = []
    for entity in response.entities:
        for indicator in unsafe_indicators:
            if indicator in entity.name.lower() or indicator in entity.type.name.lower():
                found_unsafe_terms.append(entity.name)
                break

    is_unsafe = len(found_unsafe_terms) > 0

    return {
        "translated_text": payload["translated_text"],
        "is_unsafe": is_unsafe,
        "found_terms": list(set(found_unsafe_terms)),
        "message": "Content deemed potentially unsafe." if is_unsafe else "Content appears safe."
    }
